import type { AuditContext } from '../../domain/audit/audit-context.js'
import { AuditAction, EntityType } from '../../domain/audit/entity-type.enum.js'
import type { ChatIdType } from '../../domain/value-objects/chatID.js'
import type { DBChatAiOptions } from '../../infrastructure/database/schema.js'
import type { AIChatOptionsPort } from '../ports/ai-chat-options.port.js'
import type { AuditLogPort } from '../ports/audit-log.port.js'
import type { LoggerPort } from '../ports/logger.port.js'

/**
 * Use case for retrieving AI configuration options for a specific chat type.
 *
 * This use case implements the business logic for fetching AI system prompts and other
 * configuration settings from the database based on the chat type ID. It follows the
 * hexagonal architecture pattern by depending on ports (interfaces) rather than concrete
 * implementations.
 *
 * **Responsibilities:**
 * - Fetch AI options (system prompts) from the repository
 * - Log audit trail for all retrieval attempts (success and failure)
 * - Handle errors gracefully and return null on failure
 * - Ensure audit logging failures don't break the main operation
 *
 * **Architecture Layer:** Application Layer (Use Case)
 *
 * @example
 * ```typescript
 * const useCase = new GetChatAiOptionsUseCase(logger, auditLog, aiChatOptionsRepo)
 * const auditContext = { userId, ipAddress: '192.168.1.1', userAgent: 'Mozilla/5.0' }
 * const options = await useCase.execute(auditContext, chatTypeId)
 * if (options) {
 *   console.log(`System prompt: ${options.prompt}`)
 * }
 * ```
 */
export class GetChatAiOptionsUseCase {
  /**
   * Creates an instance of GetChatAiOptionsUseCase.
   *
   * @param logger - Port for logging operations (errors, debug info)
   * @param auditLog - Port for recording audit trail of all data access
   * @param aiChatOptions - Port for accessing AI chat options from data source
   */
  constructor(
    private readonly logger: LoggerPort,
    private readonly auditLog: AuditLogPort,
    private readonly aiChatOptions: AIChatOptionsPort
  ) {}

  /**
   * Executes the use case to retrieve AI configuration options for a specific chat type.
   *
   * This method fetches the AI system prompt and related configuration from the database
   * via the AI chat options repository. All retrieval attempts (both successful and failed)
   * are logged to the audit trail for compliance and debugging purposes.
   *
   * **Error Handling:**
   * - If retrieval fails, the error is logged and null is returned
   * - If audit logging fails, the error is logged but the main operation continues
   * - Audit logging failures never cause the use case to fail
   *
   * **Audit Trail:**
   * - Success: Logs FETCH action with reason 'chat_options_retrieved_successfully_for_internal'
   * - Failure: Logs FETCH action with reason 'chat_options_failed_to_retrieve_for_internal'
   *
   * @param auditContext - Context information for audit logging (user ID, IP address, user agent)
   * @param chatTypeId - The unique identifier of the chat type to retrieve options for
   * @returns Promise resolving to an object containing the system prompt, or null if not found or on error
   *
   * @example
   * ```typescript
   * const auditContext = {
   *   userId: new UserId('user-123').getValue(),
   *   ipAddress: '192.168.1.100',
   *   userAgent: 'Mozilla/5.0'
   * }
   * const chatTypeId = new ChatId('019bdccc-f0cb-7322-aa9e-776e25f34d81').getValue()
   * const result = await useCase.execute(auditContext, chatTypeId)
   * if (result) {
   *   console.log(`System prompt: ${result.prompt}`)
   * } else {
   *   console.log('Failed to retrieve AI options')
   * }
   * ```
   */
  async execute(
    auditContext: AuditContext,
    chatTypeId: ChatIdType
  ): Promise<Pick<DBChatAiOptions, 'prompt'> | null> {
    try {
      const result = await this.aiChatOptions.getChatOptionsByChatTypeId(chatTypeId)

      try {
        await this.auditLog.log({
          userId: auditContext.userId,
          entityType: EntityType.AI_OPTIONS,
          entityId: chatTypeId,
          action: AuditAction.FETCH,
          changes: { reason: 'chat_options_retrieved_successfully_for_internal' },
          ipAddress: auditContext.ipAddress,
          userAgent: auditContext.userAgent ?? undefined,
        })
      } catch (error) {
        this.logger.error('Error logging audit for chat retrieval', error as Error, {
          event: 'chat_options.audit.failed',
          userId: auditContext.userId,
        })
      }
      return result ?? null
    } catch (error) {
      this.logger.error('Error in GetChatAiOptionsUseCase.execute', error as Error, {
        event: 'chat_options.fetch.failed',
        chatTypeId,
      })
      await this.auditLog.log({
        userId: auditContext.userId,
        entityType: EntityType.AI_OPTIONS,
        entityId: chatTypeId,
        action: AuditAction.FETCH,
        changes: { reason: 'chat_options_failed_to_retrieve_for_internal' },
        ipAddress: auditContext.ipAddress,
        userAgent: auditContext.userAgent ?? undefined,
      })
      return null
    }
  }
}

src/infrastructure/ai/middleware/cache.m.source:
import { TransformStream } from 'node:stream/web'
import { promisify } from 'node:util'
import { gunzip as gunzipCb, gzip as gzipCb } from 'node:zlib'

import {
  type LanguageModelV3,
  type LanguageModelV3Middleware,
  type LanguageModelV3StreamPart,
} from '@ai-sdk/provider'
import { UtcDate } from '@norberts-spark/shared'
import { Redis } from '@upstash/redis'
import { simulateReadableStream } from 'ai'
import { obscured } from 'obscured'

import type { LoggerPort } from '../../../application/ports/logger.port.js'
import { EnvConfig } from '../../config/env.config.js'

const gzip = promisify(gzipCb)
const gunzip = promisify(gunzipCb)
/**
 * Cache the evaluated Redis configuration to avoid repeated obscured.value() calls
 */
let isConfiguredCache: boolean | null = null
let cachedRedisUrl: string | undefined
let cachedRedisToken: string | undefined

/**
 * Check if Redis credentials are properly configured
 */
function isRedisConfigured(): boolean {
  // Return cached result if already computed
  if (isConfiguredCache !== null) {
    return isConfiguredCache
  }

  cachedRedisUrl = obscured.value(EnvConfig.UPSTASH_REDIS_REST_URL)
  cachedRedisToken = obscured.value(EnvConfig.UPSTASH_REDIS_REST_TOKEN)

  // Check if credentials exist and are not obscured placeholder values
  isConfiguredCache =
    !!cachedRedisUrl &&
    !!cachedRedisToken &&
    cachedRedisUrl !== '[OBSCURED]' &&
    cachedRedisToken !== '[OBSCURED]' &&
    cachedRedisUrl !== 'undefined' &&
    cachedRedisToken !== 'undefined'

  return isConfiguredCache
}

/**
 * Lazily initialize Redis client only when credentials are configured
 */
let redisClient: Redis | null = null
let initializationAttempted = false

function getRedisClient(logger: LoggerPort): Redis | null {
  // Return existing client if already initialized
  if (redisClient !== null) {
    return redisClient
  }

  // Check if Redis is configured
  if (!isRedisConfigured()) {
    return null
  }

  // Only attempt initialization once to avoid repeated errors
  if (initializationAttempted) {
    return null
  }

  initializationAttempted = true

  try {
    redisClient = new Redis({
      url: cachedRedisUrl!,
      token: cachedRedisToken!,
    })
    return redisClient
  } catch (error) {
    logger.error(
      'Failed to initialize Redis client',
      error instanceof Error ? error : new Error(String(error))
    )
    return null
  }
}

/**
 * Creates a LanguageModelV3Middleware that caches AI responses in Redis.
 *
 * LanguageModelMiddleware has two methods: wrapGenerate and wrapStream. wrapGenerate is called when using generateText and generateObject, while wrapStream is called when using streamText and streamObject.
 * For wrapGenerate, you can cache the response directly. Instead, for wrapStream, you cache an array of the stream parts, which can then be used with simulateReadableStream function to create a simulated ReadableStream that returns the cached response. In this way, the cached response is returned chunk-by-chunk as if it were being generated by the model. You can control the initial delay and delay between chunks by adjusting the initialDelayInMs and chunkDelayInMs parameters of simulateReadableStream.
 * https://ai-sdk.dev/docs/advanced/caching
 *
 * @param logger - Pino-backed logger used for debug/error messages
 */
export function createCacheMiddleware(logger: LoggerPort): LanguageModelV3Middleware {
  return {
    specificationVersion: 'v3',
    wrapGenerate: async ({ doGenerate, params }) => {
      const cacheKey = JSON.stringify(params)
      const redis = getRedisClient(logger)

      // Try to get from cache if Redis is configured
      if (redis) {
        try {
          const raw = (await redis.get(cacheKey)) as string | null

          if (raw !== null) {
            const cached = JSON.parse(
              (await gunzip(Buffer.from(raw, 'base64'))).toString()
            ) as Awaited<ReturnType<LanguageModelV3['doGenerate']>>

            logger.debug('wrapGenerate: cache hit — returning cached response', {
              middleware: 'cache-middleware',
            })
            return {
              ...cached,
              response: {
                ...cached.response,
                timestamp: cached?.response?.timestamp
                  ? new Date(cached?.response?.timestamp)
                  : undefined,
              },
            }
          }

          logger.debug('wrapGenerate: cache miss — calling model', {
            middleware: 'cache-middleware',
          })
        } catch (error) {
          logger.error(
            'Cache read error in wrapGenerate',
            error instanceof Error ? error : new Error(String(error)),
            { middleware: 'cache-middleware' }
          )
          // Continue without cache - graceful degradation
        }
      }

      const result = await doGenerate()

      // Try to cache the result if Redis is configured
      if (redis) {
        try {
          const compressed = (await gzip(Buffer.from(JSON.stringify(result)))).toString('base64')
          await redis.set(cacheKey, compressed, { ex: 3600 })
          logger.debug('wrapGenerate: response written to cache', {
            middleware: 'cache-middleware',
          })
        } catch (error) {
          logger.error(
            'Cache write error in wrapGenerate',
            error instanceof Error ? error : new Error(String(error)),
            { middleware: 'cache-middleware' }
          )
          // Continue without caching - graceful degradation
        }
      }

      return result
    },
    wrapStream: async ({ doStream, params }) => {
      const cacheKey = JSON.stringify(params)
      const redis = getRedisClient(logger)

      // Try to check if the result is in the cache if Redis is configured
      if (redis) {
        try {
          const raw = (await redis.get(cacheKey)) as string | null

          // If cached, return a simulated ReadableStream that yields the cached result
          if (raw !== null) {
            const cached = JSON.parse(
              (await gunzip(Buffer.from(raw, 'base64'))).toString()
            ) as LanguageModelV3StreamPart[]

            logger.debug('wrapStream: cache hit — returning simulated stream', {
              middleware: 'cache-middleware',
            })
            // Format the timestamps in the cached response
            const formattedChunks = cached.map((p) => {
              if (p.type === 'response-metadata' && p.timestamp) {
                return { ...p, timestamp: UtcDate.create(p.timestamp).toDate() }
              } else return p
            })
            return {
              stream: simulateReadableStream({
                initialDelayInMs: 0,
                chunkDelayInMs: 10,
                chunks: formattedChunks,
              }),
            }
          }
          logger.debug('wrapStream: cache miss — calling model', { middleware: 'cache-middleware' })
        } catch (error) {
          logger.error(
            'Cache read error in wrapStream',
            error instanceof Error ? error : new Error(String(error)),
            { middleware: 'cache-middleware' }
          )
          // Continue without cache - graceful degradation
        }
      }

      // If not cached, proceed with streaming
      const { stream, ...rest } = await doStream()

      const fullResponse: LanguageModelV3StreamPart[] = []

      const transformStream = new TransformStream<
        LanguageModelV3StreamPart,
        LanguageModelV3StreamPart
      >({
        transform(chunk, controller) {
          fullResponse.push(chunk)
          controller.enqueue(chunk)
        },
        async flush() {
          // Try to store the full response in the cache after streaming is complete if Redis is configured
          if (redis) {
            try {
              const compressed = (await gzip(Buffer.from(JSON.stringify(fullResponse)))).toString(
                'base64'
              )
              await redis.set(cacheKey, compressed, { ex: 3600 })
              logger.debug('wrapStream: response written to cache', {
                middleware: 'cache-middleware',
              })
            } catch (error) {
              logger.error(
                'Cache write error in wrapStream flush',
                error instanceof Error ? error : new Error(String(error)),
                { middleware: 'cache-middleware' }
              )
              // Continue without caching - graceful degradation
            }
          }
        },
      })

      return {
        stream: stream.pipeThrough(transformStream),
        ...rest,
      }
    },
  }
}

