src/application/use-cases/get-chat.use-c.source:
import type { MessageSchemaType } from '@norberts-spark/shared'

import type { ChatResponseResult } from '../../adapters/secondary/repositories/ai.repository.js'
import type { FetchChatChanges } from '../../domain/audit/audit-changes.types.js'
import type { AuditContext } from '../../domain/audit/audit-context.js'
import { AuditAction, EntityType } from '../../domain/audit/entity-type.enum.js'
import type { ChatIdType } from '../../domain/value-objects/chatID.js'
import type { AIServicePort } from '../ports/ai.port.js'
import type { AuditLogPort, CreateAuditLogDTO } from '../ports/audit-log.port.js'
import type { LoggerPort } from '../ports/logger.port.js'
/**
 * Use case for retrieving chat messages for a specific user
 *
 * This use case handles the retrieval of chat messages and their associated parts
 * from the database. It validates the user ID format before querying the repository.
 *
 * @class GetChatUseCase
 * @example
 * ```typescript
 * const useCase = new GetChatUseCase(aiRepository, logger)
 * const result = await useCase.execute('01943e6d-1234-7890-abcd-1234567890ab')
 * ```
 */
export class GetChatUseCase {
  /**
   * Creates an instance of GetChatUseCase
   * @param {AIServicePort} aiService - Service for handling AI-related operations
   * @param {LoggerPort} logger - Logger for tracking operations
   * @param {AuditLogPort} auditLog - Audit logging service for recording user registration events
   */
  constructor(
    private readonly aiService: AIServicePort,
    private readonly logger: LoggerPort,
    private readonly auditLog: AuditLogPort
  ) {}

  /**
   * Executes the get chat use case
   *
   * Validates the user ID format (must be UUID v7) and retrieves all chat messages
   * and their associated parts for the given user.
   *
   * @param chatID
   * @param messages
   * @param auditContext
   * @returns {Promise<ChatResponseResult | null>} Chat messages with parts, or null if not found
   * @throws {ValidationException} If the userId is not a valid UUID v7
   * @example
   * ```typescript
   * try {
   *   const chatData = await useCase.execute('01943e6d-1234-7890-abcd-1234567890ab')
   *   if (chatData) {
   *     console.log(`Found ${chatData.length} messages`)
   *   }
   * } catch (error) {
   *   if (error instanceof ValidationException) {
   *     console.error('Invalid user ID format')
   *   }
   * }
   * ```
   */
  async execute(
    chatID: ChatIdType,
    messages: MessageSchemaType[] = [],
    auditContext: AuditContext
  ): Promise<ChatResponseResult | null> {
    this.logger.info('Getting chat', { event: 'chat.fetch.attempt', chatId: chatID })

    // Retrieve chat data from DB
    const chatData = await this.aiService.getChatResponse(chatID)

    if (chatData && chatData.length > 0) {
      this.logger.info('Chat data retrieved successfully', {
        event: 'chat.fetch.success',
        chatId: chatID,
        messageCount: chatData.length,
      })

      const auditEntry: CreateAuditLogDTO = {
        userId: auditContext.userId,
        entityType: EntityType.CHAT,
        entityId: chatID,
        action: AuditAction.FETCH,
        changes: {
          chatIds: chatData.map((chat) => chat.chat.id),
          reason: 'chat_successfully_retrieved',
        } satisfies FetchChatChanges,
        ipAddress: auditContext.ipAddress,
        userAgent: auditContext.userAgent ?? undefined,
      }
      // AuditLogPort.log() never throws per contract
      await this.auditLog.log(auditEntry)
    } else {
      this.logger.info('No chat data found for user', {
        event: 'chat.fetch.not_found',
        chatId: chatID,
      })
      return null
    }

    return chatData
  }
}

src/application/use-cases/get-chats-by-u.source:
import type {
  FetchChatChanges,
  FetchChatFailedChanges,
} from '../../domain/audit/audit-changes.types.js'
import type { AuditContext } from '../../domain/audit/audit-context.js'
import { AuditAction, EntityType } from '../../domain/audit/entity-type.enum.js'
import type { UserIdType } from '../../domain/value-objects/userID.js'
import type { AIServicePort, ChatWithType } from '../ports/ai.port.js'
import type { AuditLogPort, CreateAuditLogDTO } from '../ports/audit-log.port.js'
import type { LoggerPort } from '../ports/logger.port.js'

/**
 * Application use-case — retrieves all chat sessions belonging to a user.
 *
 * Orchestrates two steps:
 * 1. Delegates the database read to {@link AIServicePort} (backed by
 *    {@link AIRepository}) via `getChatsByUserId`.
 * 2. Writes a `FETCH` audit log entry on success (recording the list of
 *    returned chat IDs) or a `FETCH_FAILED` entry on error, both via
 *    {@link AuditLogPort} (fire-and-forget; audit failures never propagate).
 *    On error the original exception is re-thrown so the caller can map it
 *    to an HTTP status code.
 *
 * This use-case is called from {@link AIController.getAIChatsByUserId} to
 * serve the `GET /ai/chats/:userId` endpoint.
 */
export class GetChatsByUserIdUseCase {
  constructor(
    private readonly aiRepository: AIServicePort,
    private readonly logger: LoggerPort,
    private readonly auditLog: AuditLogPort
  ) {}

  /**
   * Fetches all chats for the given user and writes an audit log entry.
   *
   * On success a `FETCH` audit entry is written with `reason:
   * 'chat_successfully_retrieved_by_userid'` and the list of returned chat
   * IDs. On failure a `FETCH_FAILED` entry is written and the original
   * error is re-thrown.
   *
   * @param userId - The branded UUID of the user whose chats to retrieve.
   * @param auditContext - Caller context used to populate the audit log entry
   *   (`userId`, `ipAddress`, `userAgent`).
   * @returns A promise that resolves to an array of {@link ChatWithType}
   *   objects (chat record joined with its chat-type details). Returns an
   *   empty array when the user has no chats.
   *
   * @throws Re-throws any error thrown by {@link AIServicePort.getChatsByUserId}.
   *
   * @example
   * const chats = await getChatsByUserIdUseCase.execute(userId, auditContext)
   * // chats[0].id — ChatIdType of the first chat
   * // chats[0].chatType — associated chat-type details
   */
  async execute(userId: UserIdType, auditContext: AuditContext): Promise<ChatWithType[]> {
    this.logger.info('Getting chats for user', { event: 'chat.fetch_by_user.attempt', userId })

    let chats: ChatWithType[]
    try {
      chats = await this.aiRepository.getChatsByUserId(userId)
    } catch (error) {
      this.logger.error('Error retrieving chats for user', error as Error, {
        event: 'chat.fetch_by_user.failed',
        userId,
      })

      const auditEntry: CreateAuditLogDTO = {
        userId: auditContext.userId,
        entityType: EntityType.CHAT,
        entityId: userId,
        action: AuditAction.FETCH_FAILED,
        changes: {
          reason: 'chat_retrieval_failed',
          errorMessage: error instanceof Error ? error.message : 'Unknown error',
        } satisfies FetchChatFailedChanges,
        ipAddress: auditContext.ipAddress,
        userAgent: auditContext.userAgent ?? undefined,
      }
      // AuditLogPort.log() never throws per contract
      await this.auditLog.log(auditEntry)

      throw error
    }

    this.logger.info('Retrieved chats for user', {
      event: 'chat.fetch_by_user.success',
      userId,
      count: chats.length,
    })

    const auditEntry: CreateAuditLogDTO = {
      userId: auditContext.userId,
      entityType: EntityType.CHAT,
      entityId: userId,
      action: AuditAction.FETCH,
      changes: {
        reason: 'chat_successfully_retrieved_by_userid',
        chatIds: chats.map((c) => c.id),
      } satisfies FetchChatChanges,
      ipAddress: auditContext.ipAddress,
      userAgent: auditContext.userAgent ?? undefined,
    }
    // AuditLogPort.log() never throws per contract
    await this.auditLog.log(auditEntry)

    return chats
  }
}

src/infrastructure/database/index.ts.source:
import { instrumentDrizzleClient } from '@kubiks/otel-drizzle'
import { drizzle } from 'drizzle-orm/node-postgres'
import { obscured } from 'obscured'
import { Pool } from 'pg'

import { ValidationException } from '../../shared/exceptions/validation.exception.js'
import { EnvConfig } from '../config/env.config.js'

const logger = {
  info: (...params: unknown[]) => console.info(...params),
  error: (...params: unknown[]) => console.error(...params),
}

logger.info('Connecting to database...')

if (!obscured.value(EnvConfig.DATABASE_URL)) {
  throw new ValidationException('DATABASE_URL is required but not configured')
}

export const pool = new Pool({
  connectionString: obscured.value(EnvConfig.DATABASE_URL),
  ssl:
    String(EnvConfig.DATABASE_SSL_ENABLED) === 'true'
      ? { rejectUnauthorized: String(EnvConfig.DATABASE_SSL_REJECT_UNAUTHORIZED) !== 'false' }
      : false,
  connectionTimeoutMillis: Number(EnvConfig.DATABASE_CONNECTION_TIMEOUT_MS),
  idleTimeoutMillis: Number(EnvConfig.DATABASE_IDLE_TIMEOUT_MS),
  max: Number(EnvConfig.DATABASE_POOL_MAX),
  min: Number(EnvConfig.DATABASE_POOL_MIN),
  maxLifetimeSeconds: Number(EnvConfig.DATABASE_POOL_MAX_LIFETIME_SECONDS),
})

pool.on('error', (err) => {
  logger.error('Unexpected error on idle client', err)
  process.exit(-1)
})

const db = drizzle(pool)

const shouldCaptureQueryText =
  EnvConfig.NODE_ENV !== 'production' && EnvConfig.OTEL_CAPTURE_QUERY_TEXT

const instrumentedDb = instrumentDrizzleClient(db, {
  captureQueryText: shouldCaptureQueryText,
  maxQueryTextLength: 500,
})

export { instrumentedDb as db }

