import { uuidv7 } from 'uuidv7'
import { beforeEach, describe, expect, it, vi } from 'vitest'

import { RegisterUserDto } from '../../../src/application/dtos/register-user.dto.js'
import type { AuditLogPort } from '../../../src/application/ports/audit-log.port.js'
import type { EmailServicePort } from '../../../src/application/ports/email.service.port.js'
import type { LoggerPort } from '../../../src/application/ports/logger.port.js'
import type { TokenGeneratorPort } from '../../../src/application/ports/token-generator.port.js'
import type { UserRepositoryPort } from '../../../src/application/ports/user.repository.port.js'
import { RegisterUserUseCase } from '../../../src/application/use-cases/register-user.use-case.js'
import { AuditAction, EntityType } from '../../../src/domain/audit/entity-type.enum.js'
import { User } from '../../../src/domain/entities/user.js'
import { UserId, type UserIdType } from '../../../src/domain/value-objects/userID.js'
import { ConflictException } from '../../../src/shared/exceptions/conflict.exception.js'
import { ValidationException } from '../../../src/shared/exceptions/validation.exception.js'
import { createMockLogger } from '../../shared/factories/logger.factory.js'

// Helper function to create mock UserIdType from UUID string
function createMockUserId(uuid?: string): UserIdType {
  return new UserId(uuid || uuidv7()).getValue()
}

describe('RegisterUserUseCase', () => {
  let useCase: RegisterUserUseCase
  let mockUserRepository: UserRepositoryPort
  let mockEmailService: EmailServicePort
  let mockLogger: LoggerPort
  let mockTokenGenerator: TokenGeneratorPort
  let mockAuditLog: AuditLogPort
  const auditContext = { userId: null, ipAddress: '127.0.0.1', userAgent: 'test-agent' }

  beforeEach(() => {
    // Reset all mocks before each test
    vi.clearAllMocks()

    // Create mock implementations
    mockUserRepository = {
      save: vi.fn(),
      findById: vi.fn(),
      findByEmail: vi.fn(),
      findAll: vi.fn(),
      update: vi.fn(),
      delete: vi.fn(),
      deleteUsers: vi.fn(),
      existsByEmail: vi.fn(),
      saveProvider: vi.fn(),
    }

    mockEmailService = {
      sendWelcomeEmail: vi.fn(),
      sendPasswordResetEmail: vi.fn(),
    }

    mockLogger = createMockLogger()

    mockTokenGenerator = {
      generateToken: vi.fn().mockReturnValue('mock-jwt-token'),
    }

    mockAuditLog = {
      log: vi.fn().mockResolvedValue(undefined),
      getByEntity: vi.fn(),
      getByUser: vi.fn(),
      getByAction: vi.fn(),
    }

    // Create use case instance with mocks
    useCase = new RegisterUserUseCase(
      mockUserRepository,
      mockEmailService,
      mockLogger,
      mockTokenGenerator,
      mockAuditLog
    )
  })

  describe('execute()', () => {
    describe('successful registration', () => {
      it('should register a new user successfully', async () => {
        const dto = new RegisterUserDto('john@example.com', 'John Doe', 'user', 'SecurePass123!')

        vi.mocked(mockUserRepository.save).mockResolvedValue(createMockUserId())
        vi.mocked(mockEmailService.sendWelcomeEmail).mockResolvedValue(undefined)

        const result = await useCase.execute(dto, auditContext)

        // Should return a user ID
        expect(result).toBeDefined()
        expect(result.userId).toBeDefined()
        expect(typeof result.userId).toBe('string')
        expect(result.userId).toMatch(
          /^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
        )
      })

      it('should log successful registration to audit log', async () => {
        const dto = new RegisterUserDto('john@example.com', 'John Doe', 'user', 'SecurePass123!')
        const mockUserId = createMockUserId()

        vi.mocked(mockUserRepository.save).mockResolvedValue(mockUserId)
        vi.mocked(mockEmailService.sendWelcomeEmail).mockResolvedValue(undefined)

        await useCase.execute(dto, auditContext)

        expect(mockAuditLog.log).toHaveBeenCalledTimes(1)
        expect(mockAuditLog.log).toHaveBeenCalledWith({
          userId: mockUserId,
          entityType: EntityType.USER,
          entityId: mockUserId,
          action: AuditAction.CREATE,
          changes: { reason: 'new_user' },
          ipAddress: auditContext.ipAddress,
          userAgent: auditContext.userAgent,
        })
      })

      it('should save the user to the repository', async () => {
        const dto = new RegisterUserDto('john@example.com', 'John Doe', 'user', 'SecurePass123!')

        vi.mocked(mockUserRepository.save).mockResolvedValue(createMockUserId())
        vi.mocked(mockEmailService.sendWelcomeEmail).mockResolvedValue(undefined)

        await useCase.execute(dto, auditContext)

        expect(mockUserRepository.save).toHaveBeenCalledTimes(1)

        const savedUser = vi.mocked(mockUserRepository.save).mock.calls?.[0]?.[0]
        expect(savedUser).toBeInstanceOf(User)
        expect(savedUser?.getEmail()).toBe('john@example.com')
      })

      it('should send a welcome email to the user', async () => {
        const dto = new RegisterUserDto('john@example.com', 'John Doe', 'user', 'SecurePass123!')

        vi.mocked(mockUserRepository.save).mockResolvedValue(createMockUserId())
        vi.mocked(mockEmailService.sendWelcomeEmail).mockResolvedValue(undefined)

        await useCase.execute(dto, auditContext)

        expect(mockEmailService.sendWelcomeEmail).toHaveBeenCalledTimes(1)
        expect(mockEmailService.sendWelcomeEmail).toHaveBeenCalledWith(
          'john@example.com',
          'John Doe'
        )
      })

      it('should log registration start with email', async () => {
        const dto = new RegisterUserDto('john@example.com', 'John Doe', 'user', 'SecurePass123!')

        vi.mocked(mockUserRepository.save).mockResolvedValue(createMockUserId())
        vi.mocked(mockEmailService.sendWelcomeEmail).mockResolvedValue(undefined)

        await useCase.execute(dto, auditContext)

        expect(mockLogger.info).toHaveBeenCalledWith('Starting user registration', {
          event: 'user.registration.attempt',
        })
      })

      it('should log successful registration with userId', async () => {
        const dto = new RegisterUserDto('john@example.com', 'John Doe', 'user', 'SecurePass123!')

        vi.mocked(mockUserRepository.save).mockResolvedValue(createMockUserId())
        vi.mocked(mockEmailService.sendWelcomeEmail).mockResolvedValue(undefined)

        const result = await useCase.execute(dto, auditContext)

        expect(mockLogger.info).toHaveBeenCalledWith('User registered successfully', {
          event: 'user.registered',
          userId: result.userId,
        })
      })

      it('should create unique user IDs for different registrations', async () => {
        const dto1 = new RegisterUserDto('john@example.com', 'John Doe', 'user', 'SecurePass123!')
        const dto2 = new RegisterUserDto('jane@example.com', 'Jane Smith', 'user', 'SecurePass456!')

        vi.mocked(mockUserRepository.save).mockImplementation(() =>
          Promise.resolve(createMockUserId())
        )
        vi.mocked(mockEmailService.sendWelcomeEmail).mockResolvedValue(undefined)

        const result1 = await useCase.execute(dto1, auditContext)
        const result2 = await useCase.execute(dto2, auditContext)

        expect(result1.userId).not.toBe(result2.userId)
      })
    })

    describe('duplicate email handling', () => {
      it('should throw ConflictException when database rejects duplicate email', async () => {
        const dto = new RegisterUserDto(
          'existing@example.com',
          'John Doe',
          'user',
          'SecurePass123!'
        )

        // Simulate PostgreSQL unique constraint violation error (code 23505)
        const duplicateKeyError = Object.assign(
          new Error('duplicate key value violates unique constraint'),
          {
            code: '23505',
          }
        )
        vi.mocked(mockUserRepository.save).mockRejectedValue(duplicateKeyError)

        await expect(useCase.execute(dto, auditContext)).rejects.toThrow(ConflictException)
        await expect(useCase.execute(dto, auditContext)).rejects.toThrow(
          'User with this email already exists'
        )
      })

      it('should not send welcome email when duplicate email is detected', async () => {
        const dto = new RegisterUserDto(
          'existing@example.com',
          'John Doe',
          'user',
          'SecurePass123!'
        )

        const duplicateKeyError = Object.assign(
          new Error('duplicate key value violates unique constraint'),
          {
            code: '23505',
          }
        )
        vi.mocked(mockUserRepository.save).mockRejectedValue(duplicateKeyError)

        await expect(useCase.execute(dto, auditContext)).rejects.toThrow(ConflictException)

        expect(mockEmailService.sendWelcomeEmail).not.toHaveBeenCalled()
      })

      it('should log duplicate email failure to audit log', async () => {
        const dto = new RegisterUserDto(
          'duplicate@example.com',
          'Test User',
          'user',
          'SecurePass123!'
        )

        const duplicateKeyError = Object.assign(
          new Error('duplicate key value violates unique constraint'),
          {
            code: '23505',
          }
        )
        vi.mocked(mockUserRepository.save).mockRejectedValue(duplicateKeyError)

        await expect(useCase.execute(dto, auditContext)).rejects.toThrow(ConflictException)

        expect(mockAuditLog.log).toHaveBeenCalledTimes(1)
        expect(mockAuditLog.log).toHaveBeenCalledWith({
          userId: null,
          entityType: EntityType.USER,
          entityId: 'duplicate@example.com',
          action: AuditAction.REGISTRATION_FAILED,
          changes: { reason: 'duplicate_email' },
          ipAddress: auditContext.ipAddress,
          userAgent: auditContext.userAgent,
        })
      })

      it('should handle race condition with concurrent duplicate registrations', async () => {
        const dto = new RegisterUserDto('race@example.com', 'Test User', 'user', 'SecurePass123!')

        // Simulate race condition where both requests get past any checks
        // but database rejects the second one
        const duplicateKeyError = Object.assign(
          new Error('duplicate key value violates unique constraint'),
          {
            code: '23505',
          }
        )
        vi.mocked(mockUserRepository.save).mockRejectedValue(duplicateKeyError)

        await expect(useCase.execute(dto, auditContext)).rejects.toThrow(ConflictException)
        await expect(useCase.execute(dto, auditContext)).rejects.toThrow(
          'User with this email already exists'
        )
      })
    })

    describe('email service failure handling', () => {
      it('should not fail registration if welcome email fails to send', async () => {
        const dto = new RegisterUserDto('john@example.com', 'John Doe', 'user', 'SecurePass123!')

        vi.mocked(mockUserRepository.save).mockResolvedValue(createMockUserId())
        vi.mocked(mockEmailService.sendWelcomeEmail).mockRejectedValue(
          new Error('Email service down')
        )

        const result = await useCase.execute(dto, auditContext)

        // Should still return userId despite email failure
        expect(result).toBeDefined()
        expect(result.userId).toBeDefined()
      })

      it('should log error when welcome email fails to send', async () => {
        const dto = new RegisterUserDto('john@example.com', 'John Doe', 'user', 'SecurePass123!')

        vi.mocked(mockUserRepository.save).mockResolvedValue(createMockUserId())

        const emailError = new Error('Email service down')
        vi.mocked(mockEmailService.sendWelcomeEmail).mockRejectedValue(emailError)

        const result = await useCase.execute(dto, auditContext)

        expect(mockLogger.error).toHaveBeenCalledTimes(1)
        expect(mockLogger.error).toHaveBeenCalledWith('Failed to send welcome email', emailError, {
          event: 'user.welcome_email.failed',
          userId: result.userId,
        })
      })

      it('should still save user even if email service fails', async () => {
        const dto = new RegisterUserDto('john@example.com', 'John Doe', 'user', 'SecurePass123!')

        vi.mocked(mockUserRepository.save).mockResolvedValue(createMockUserId())
        vi.mocked(mockEmailService.sendWelcomeEmail).mockRejectedValue(
          new Error('Email service down')
        )

        await useCase.execute(dto, auditContext)

        expect(mockUserRepository.save).toHaveBeenCalledTimes(1)
      })
    })

    describe('domain object creation', () => {
      it('should create Email value object from dto email', async () => {
        const dto = new RegisterUserDto('test@example.com', 'Test User', 'user', 'SecurePass123!')

        vi.mocked(mockUserRepository.save).mockResolvedValue(createMockUserId())
        vi.mocked(mockEmailService.sendWelcomeEmail).mockResolvedValue(undefined)

        await useCase.execute(dto, auditContext)

        const savedUser = vi.mocked(mockUserRepository.save).mock.calls?.[0]?.[0]
        expect(savedUser).toBeInstanceOf(User)
        expect(savedUser?.getEmail()).toBe('test@example.com')
      })

      it('should create Password value object from dto password', async () => {
        const dto = new RegisterUserDto('test@example.com', 'Test User', 'user', 'SecurePass123!')

        vi.mocked(mockUserRepository.save).mockResolvedValue(createMockUserId())
        vi.mocked(mockEmailService.sendWelcomeEmail).mockResolvedValue(undefined)

        await useCase.execute(dto, auditContext)

        const savedUser = vi.mocked(mockUserRepository.save).mock.calls?.[0]?.[0]

        // Password should be hashed and verifiable via updatePassword
        // User entity doesn't expose direct password verification
        // But we can verify it was created properly by checking it's a User instance
        expect(savedUser).toBeInstanceOf(User)
      })

      it('should create User entity with all properties', async () => {
        const dto = new RegisterUserDto('test@example.com', 'Test User', 'user', 'SecurePass123!')

        vi.mocked(mockUserRepository.save).mockResolvedValue(createMockUserId())
        vi.mocked(mockEmailService.sendWelcomeEmail).mockResolvedValue(undefined)

        await useCase.execute(dto, auditContext)

        const savedUser = vi.mocked(mockUserRepository.save).mock.calls?.[0]?.[0]
        expect(savedUser).toBeInstanceOf(User)
        expect(savedUser?.getEmail()).toBe('test@example.com')
      })

      it('should throw ValidationException for invalid email format', async () => {
        const dto = new RegisterUserDto('invalid-email', 'Test User', 'user', 'SecurePass123!')

        // Email validation happens when creating Email value object
        await expect(useCase.execute(dto, auditContext)).rejects.toThrow(ValidationException)
        await expect(useCase.execute(dto, auditContext)).rejects.toThrow('Invalid email format')
      })

      it('should throw ValidationException for weak password', async () => {
        const dto = new RegisterUserDto('test@example.com', 'Test User', 'user', 'weak')

        // Password validation happens when creating Password value object
        await expect(useCase.execute(dto, auditContext)).rejects.toThrow(ValidationException)
        await expect(useCase.execute(dto, auditContext)).rejects.toThrow(
          'Password must be at least 8 characters'
        )
      })
    })

    describe('repository failure handling', () => {
      it('should throw error when repository save fails with non-duplicate error', async () => {
        const dto = new RegisterUserDto('test@example.com', 'Test User', 'user', 'SecurePass123!')

        vi.mocked(mockUserRepository.save).mockRejectedValue(
          new Error('Database connection failed')
        )

        await expect(useCase.execute(dto, auditContext)).rejects.toThrow(
          'Database connection failed'
        )
      })

      it('should not log to audit log when repository save fails with non-duplicate error', async () => {
        const dto = new RegisterUserDto('test@example.com', 'Test User', 'user', 'SecurePass123!')

        vi.mocked(mockUserRepository.save).mockRejectedValue(
          new Error('Database connection failed')
        )

        await expect(useCase.execute(dto, auditContext)).rejects.toThrow()

        // Audit log should not be called for general database errors
        expect(mockAuditLog.log).not.toHaveBeenCalled()
      })

      it('should not send email if repository save fails', async () => {
        const dto = new RegisterUserDto('test@example.com', 'Test User', 'user', 'SecurePass123!')

        vi.mocked(mockUserRepository.save).mockRejectedValue(
          new Error('Database connection failed')
        )

        await expect(useCase.execute(dto, auditContext)).rejects.toThrow()

        // Email should not be sent if save fails
        expect(mockEmailService.sendWelcomeEmail).not.toHaveBeenCalled()
      })
    })

    describe('edge cases', () => {
      it('should handle very long names', async () => {
        const longName = 'A'.repeat(500)
        const dto = new RegisterUserDto('test@example.com', longName, 'user', 'SecurePass123!')

        vi.mocked(mockUserRepository.save).mockResolvedValue(createMockUserId())
        vi.mocked(mockEmailService.sendWelcomeEmail).mockResolvedValue(undefined)

        const result = await useCase.execute(dto, auditContext)

        expect(result.userId).toBeDefined()

        const savedUser = vi.mocked(mockUserRepository.save).mock.calls?.[0]?.[0]
        expect(savedUser).toBeInstanceOf(User)
        expect(savedUser?.getEmail()).toBe('test@example.com')
      })

      it('should handle special characters in name', async () => {
        const specialName = "O'Brien-Smith (Jr.) <test@example.com>"
        const dto = new RegisterUserDto('test@example.com', specialName, 'user', 'SecurePass123!')

        vi.mocked(mockUserRepository.save).mockResolvedValue(createMockUserId())
        vi.mocked(mockEmailService.sendWelcomeEmail).mockResolvedValue(undefined)

        const result = await useCase.execute(dto, auditContext)

        expect(result.userId).toBeDefined()

        const savedUser = vi.mocked(mockUserRepository.save).mock.calls?.[0]?.[0]
        expect(savedUser).toBeInstanceOf(User)
        expect(savedUser?.getEmail()).toBe('test@example.com')
      })

      it('should handle email with subdomain', async () => {
        const dto = new RegisterUserDto(
          'user@mail.company.co.uk',
          'Test User',
          'user',
          'SecurePass123!'
        )

        vi.mocked(mockUserRepository.save).mockResolvedValue(createMockUserId())
        vi.mocked(mockEmailService.sendWelcomeEmail).mockResolvedValue(undefined)

        const result = await useCase.execute(dto, auditContext)

        expect(result.userId).toBeDefined()
      })

      it('should handle concurrent registrations with different emails', async () => {
        const dto1 = new RegisterUserDto('user1@example.com', 'User One', 'user', 'SecurePass123!')
        const dto2 = new RegisterUserDto('user2@example.com', 'User Two', 'user', 'SecurePass456!')
        const dto3 = new RegisterUserDto(
          'user3@example.com',
          'User Three',
          'user',
          'SecurePass789!'
        )

        vi.mocked(mockUserRepository.save).mockImplementation(() =>
          Promise.resolve(createMockUserId())
        )
        vi.mocked(mockEmailService.sendWelcomeEmail).mockResolvedValue(undefined)

        const [result1, result2, result3] = await Promise.all([
          useCase.execute(dto1, auditContext),
          useCase.execute(dto2, auditContext),
          useCase.execute(dto3, auditContext),
        ])

        // All should have unique IDs
        expect(result1.userId).not.toBe(result2.userId)
        expect(result2.userId).not.toBe(result3.userId)
        expect(result1.userId).not.toBe(result3.userId)

        // All should have saved
        expect(mockUserRepository.save).toHaveBeenCalledTimes(3)
      })
    })

    describe('logging behavior', () => {
      it('should call logger methods in correct order', async () => {
        const dto = new RegisterUserDto('test@example.com', 'Test User', 'user', 'SecurePass123!')

        vi.mocked(mockUserRepository.save).mockResolvedValue(createMockUserId())
        vi.mocked(mockEmailService.sendWelcomeEmail).mockResolvedValue(undefined)

        await useCase.execute(dto, auditContext)

        const infoCalls = vi.mocked(mockLogger.info).mock.calls
        expect(infoCalls).toHaveLength(2)
        expect(infoCalls?.[0]?.[0]).toBe('Starting user registration')
        expect(infoCalls?.[1]?.[0]).toBe('User registered successfully')
      })

      it('should only log error when email service fails', async () => {
        const dto = new RegisterUserDto('test@example.com', 'Test User', 'user', 'SecurePass123!')

        vi.mocked(mockUserRepository.save).mockResolvedValue(createMockUserId())
        vi.mocked(mockEmailService.sendWelcomeEmail).mockRejectedValue(new Error('Email failed'))

        await useCase.execute(dto, auditContext)

        expect(mockLogger.error).toHaveBeenCalledTimes(1)
        expect(mockLogger.warn).not.toHaveBeenCalled()
      })

      it('should not log error when registration is successful', async () => {
        const dto = new RegisterUserDto('test@example.com', 'Test User', 'user', 'SecurePass123!')

        vi.mocked(mockUserRepository.save).mockResolvedValue(createMockUserId())
        vi.mocked(mockEmailService.sendWelcomeEmail).mockResolvedValue(undefined)

        await useCase.execute(dto, auditContext)

        expect(mockLogger.error).not.toHaveBeenCalled()
      })
    })

    describe('return value', () => {
      it('should return object with userId property', async () => {
        const dto = new RegisterUserDto('test@example.com', 'Test User', 'user', 'SecurePass123!')

        vi.mocked(mockUserRepository.save).mockResolvedValue(createMockUserId())
        vi.mocked(mockEmailService.sendWelcomeEmail).mockResolvedValue(undefined)

        const result = await useCase.execute(dto, auditContext)

        expect(result).toHaveProperty('userId')
        expect(result).toHaveProperty('access_token')
        expect(Object.keys(result)).toEqual(['userId', 'access_token', 'token_type', 'expires_in'])
      })

      it('should return userId matching saved user id', async () => {
        const dto = new RegisterUserDto('test@example.com', 'Test User', 'user', 'SecurePass123!')

        const mockUserId = createMockUserId()
        vi.mocked(mockUserRepository.save).mockResolvedValue(mockUserId)
        vi.mocked(mockEmailService.sendWelcomeEmail).mockResolvedValue(undefined)

        const result = await useCase.execute(dto, auditContext)

        const savedUser = vi.mocked(mockUserRepository.save).mock.calls[0]?.[0]
        expect(savedUser).toBeDefined()
        // The User entity passed into the repository represents a new aggregate,
        // so it must not have an ID yet. The persistence layer (repository/DB)
        // is responsible for generating and assigning the ID during the save
        // operation, therefore the entity we pass into save() is expected to
        // have an undefined id.
        expect(savedUser!.id).toBeUndefined()
        // The use case must then expose the ID returned by the repository back
        // to the caller, so the result.userId should match the generated ID.
        expect(result.userId).toBe(mockUserId)
      })

      it('should return access_token from token generator', async () => {
        const dto = new RegisterUserDto('test@example.com', 'Test User', 'user', 'SecurePass123!')

        vi.mocked(mockUserRepository.save).mockResolvedValue(createMockUserId())
        vi.mocked(mockEmailService.sendWelcomeEmail).mockResolvedValue(undefined)

        const result = await useCase.execute(dto, auditContext)

        expect(result.access_token).toBe('mock-jwt-token')
        expect(mockTokenGenerator.generateToken).toHaveBeenCalledTimes(1)
      })
    })

    describe('token generation', () => {
      it('should call token generator with correct user claims', async () => {
        const dto = new RegisterUserDto('test@example.com', 'Test User', 'user', 'SecurePass123!')

        const mockUserId = createMockUserId()
        vi.mocked(mockUserRepository.save).mockResolvedValue(mockUserId)
        vi.mocked(mockEmailService.sendWelcomeEmail).mockResolvedValue(undefined)

        const _result = await useCase.execute(dto, auditContext)

        expect(mockTokenGenerator.generateToken).toHaveBeenCalledWith({
          sub: mockUserId,
          email: 'test@example.com',
          roles: ['user'],
        })
      })

      it('should include admin role in token when user is admin', async () => {
        const dto = new RegisterUserDto(
          'admin@example.com',
          'Admin User',
          'admin',
          'SecurePass123!'
        )

        const mockUserId = createMockUserId()
        vi.mocked(mockUserRepository.save).mockResolvedValue(mockUserId)
        vi.mocked(mockEmailService.sendWelcomeEmail).mockResolvedValue(undefined)

        const _result = await useCase.execute(dto, auditContext)

        expect(mockTokenGenerator.generateToken).toHaveBeenCalledWith({
          sub: mockUserId,
          email: 'admin@example.com',
          roles: ['admin'],
        })
      })
    })
  })

  describe('constructor', () => {
    it('should create instance with all dependencies', () => {
      const instance = new RegisterUserUseCase(
        mockUserRepository,
        mockEmailService,
        mockLogger,
        mockTokenGenerator,
        mockAuditLog
      )

      expect(instance).toBeInstanceOf(RegisterUserUseCase)
      expect(instance).toBeDefined()
    })

    it('should store dependencies as private readonly properties', () => {
      const instance = new RegisterUserUseCase(
        mockUserRepository,
        mockEmailService,
        mockLogger,
        mockTokenGenerator,
        mockAuditLog
      )

      // Dependencies should be accessible (TypeScript private/readonly are compile-time only)
      expect(instance).toBeDefined()
    })
  })
})

