describe('AIController', () => {
  let controller: AIController
  const ENVRate = EnvConfig.NODE_ENV === 'development' || EnvConfig.NODE_ENV === 'test' ? 200 : 10

  let mockGetChatUseCase: GetChatUseCase
  let mockAppendChatUseCase: AppendedChatUseCase
  let mockSaveChatUseCase: SaveChatUseCase
  let mockGetChatsByUserIdUseCase: GetChatsByUserIdUseCase
  let mockGetChatContentByChatIdUseCase: GetChatContentByChatIdUseCase
  let mockGetChatAiOptionsUseCase: GetChatAiOptionsUseCase
  let mockResolveChatTypeUseCase: ResolveChatTypeUseCase
  let mockAuditLogPort: AuditLogPort
  let mockLogger: LoggerPort
  let mockRequest: FastifyRequest
  let mockReply: FastifyReply

  beforeEach(() => {
    // Reset all mocks before each test
    vi.clearAllMocks()

    // Create mock use cases
    mockGetChatUseCase = {
      execute: vi.fn(),
    } as any

    mockAppendChatUseCase = {
      execute: vi.fn(),
    } as any

    mockSaveChatUseCase = {
      execute: vi.fn(),
    } as any

    mockGetChatsByUserIdUseCase = {
      execute: vi.fn(),
    } as any

    mockGetChatContentByChatIdUseCase = {
      execute: vi.fn(),
    } as any

    mockGetChatAiOptionsUseCase = {
      execute: vi.fn().mockResolvedValue({
        prompt: 'You are a literary expert on Joseph Conrad\'s "Heart of Darkness"',
      }),
    } as any

    mockResolveChatTypeUseCase = {
      execute: vi.fn(),
    } as any

    // Create mock logger
    mockLogger = createMockLogger()

    // Create mock audit log port
    mockAuditLogPort = {
      log: vi.fn().mockResolvedValue(undefined),
      getByEntity: vi.fn().mockResolvedValue([]),
      getByUser: vi.fn().mockResolvedValue([]),
      getByAction: vi.fn().mockResolvedValue([]),
    } as any

    // Create controller instance with mocked dependencies
    controller = new AIController(
      mockGetChatUseCase,
      mockLogger,
      mockAppendChatUseCase,
      mockSaveChatUseCase,
      mockGetChatsByUserIdUseCase,
      mockGetChatContentByChatIdUseCase,
      mockGetChatAiOptionsUseCase,
      mockResolveChatTypeUseCase,
      mockAuditLogPort
    )

    // Create mock Fastify reply with chainable methods
    mockReply = {
      status: vi.fn().mockReturnThis(),
      send: vi.fn().mockReturnThis(),
      code: vi.fn().mockReturnThis(),
    } as any

    // Create mock Fastify request
    mockRequest = {
      id: uuidv7(),
      body: {},
      params: {},
      query: {},
      ip: '127.0.0.1',
      method: 'POST',
      routeOptions: { url: '/ai/chat' },
      headers: {
        'user-agent': 'test-user-agent',
      },
      user: {
        sub: new UserId(uuidv7()).getValue(),
        email: 'user@example.com',
      },
    } as any
  })

  describe('constructor', () => {
    it('should create instance with required dependencies', () => {
      const instance = new AIController(
        mockGetChatUseCase,
        mockLogger,
        mockAppendChatUseCase,
        mockSaveChatUseCase,
        mockGetChatsByUserIdUseCase,
        mockGetChatContentByChatIdUseCase,
        mockGetChatAiOptionsUseCase,
        mockResolveChatTypeUseCase,
        mockAuditLogPort
      )

      expect(instance).toBeInstanceOf(AIController)
      expect(instance).toBeDefined()
    })

    it('should accept GetChatUseCase, LoggerPort, and AppendedChatUseCase as dependencies', () => {
      const instance = new AIController(
        mockGetChatUseCase,
        mockLogger,
        mockAppendChatUseCase,
        mockSaveChatUseCase,
        mockGetChatsByUserIdUseCase,
        mockGetChatContentByChatIdUseCase,
