        const chatId = new ChatId(uuidv7()).getValue()

        mockRequest.params = { chatId }
        mockRequest.user = {
          sub: userId,
          email: 'user@example.com',
          roles: ['user'],
        }
        vi.mocked(mockGetChatContentByChatIdUseCase.execute).mockRejectedValue(
