import { DrizzleQueryError } from 'drizzle-orm'
import type { FastifyInstance, FastifyReply, FastifyRequest } from 'fastify'
import { uuidv7 } from 'uuidv7'
import { beforeEach, describe, expect, it, vi } from 'vitest'

import { AuthController } from '../../../../src/adapters/primary/http/auth.controller.js'
import { LogOutUseCase } from '../../../../src/application/use-cases/log-out.use-case.js'
import { LoginUserUseCase } from '../../../../src/application/use-cases/login-user.use-case.js'
import { RefreshAccessTokenUseCase } from '../../../../src/application/use-cases/refresh-access-token.use-case.js'
import { RegisterUserWithProviderUseCase } from '../../../../src/application/use-cases/register-user-with-provider.use-case.js'
import { UserId } from '../../../../src/domain/value-objects/userID.js'
import { EnvConfig } from '../../../../src/infrastructure/config/env.config.js'
import { UnauthorizedException } from '../../../../src/shared/exceptions/unauthorized.exception.js'
import { ValidationException } from '../../../../src/shared/exceptions/validation.exception.js'
import { createMockLogger } from '../../../shared/factories/logger.factory.js'

// Helper function to create mock auth result with proper UserIdType
function createMockAuthResult(email: string, token: string, roles: string[], userId?: string) {
  return {
    userId: new UserId(userId || uuidv7()).getValue(),
    email,
    accessToken: token,
    refreshToken: 'a1b2c3d4e5f6a1b2c3d4e5f6a1b2c3d4e5f6a1b2c3d4e5f6a1b2c3d4e5f6a1b2',
    expiresInSeconds: 604800,
    roles,
  }
}

describe('AuthController', () => {
  let controller: AuthController
  let mockLoginUserUseCase: LoginUserUseCase
  let mockRegisterUserWithProviderUseCase: RegisterUserWithProviderUseCase
  let mockRefreshAccessTokenUseCase: RefreshAccessTokenUseCase
  let mockLogOutUseCase: LogOutUseCase
  let mockRequest: FastifyRequest
  let mockReply: FastifyReply
  let mockLogger: {
    info: ReturnType<typeof vi.fn>
    error: ReturnType<typeof vi.fn>
    warn: ReturnType<typeof vi.fn>
    debug: ReturnType<typeof vi.fn>
    child: ReturnType<typeof vi.fn>
  }
  let mockChildLogger: typeof mockLogger
  const ENVRate = EnvConfig.NODE_ENV === 'development' || EnvConfig.NODE_ENV === 'test' ? 200 : 10

  beforeEach(() => {
    // Reset all mocks before each test
    vi.clearAllMocks()

    // Create mock use case
    mockLoginUserUseCase = {
      execute: vi.fn(),
    } as any

    mockRegisterUserWithProviderUseCase = {
      execute: vi.fn(),
    } as any

    mockRefreshAccessTokenUseCase = {
      execute: vi.fn(),
    } as any

    mockLogOutUseCase = {
      execute: vi.fn(),
    } as any

    mockChildLogger = createMockLogger() as typeof mockLogger
    mockLogger = createMockLogger() as typeof mockLogger
    mockLogger.child.mockReturnValue(mockChildLogger)

    // Create controller instance with mocked use case
    controller = new AuthController(
      mockLogger as any,
      mockLoginUserUseCase,
      mockRegisterUserWithProviderUseCase,
      mockRefreshAccessTokenUseCase,
      mockLogOutUseCase
    )

    // Create mock Fastify reply with chainable methods
    mockReply = {
      code: vi.fn().mockReturnThis(),
      send: vi.fn().mockReturnThis(),
    } as any

    // Create mock Fastify request
    mockRequest = {
      id: uuidv7(),
      body: {},
      params: {},
      query: {},
      ip: '127.0.0.1',
      method: 'POST',
      url: '/auth/login',
      routeOptions: { url: '/auth/login' },
      headers: {
        'user-agent': 'test-user-agent',
      },
    } as any
  })

  describe('constructor', () => {
    it('should create instance with LoginUserUseCase dependency', () => {
      const mockRegisterUseCase = { execute: vi.fn() } as any
      const mockRefreshUseCase = { execute: vi.fn() } as any
      const mockLogoutUseCase = { execute: vi.fn() } as any
      const mockLogger = createMockLogger()
      const instance = new AuthController(
        mockLogger,
        mockLoginUserUseCase,
        mockRegisterUseCase,
        mockRefreshUseCase,
        mockLogoutUseCase
      )

      expect(instance).toBeInstanceOf(AuthController)
      expect(instance).toBeDefined()
    })

    it('should accept LoginUserUseCase as dependency', () => {
      const mockRegisterUseCase = { execute: vi.fn() } as any
      const mockRefreshUseCase = { execute: vi.fn() } as any
      const mockLogoutUseCase = { execute: vi.fn() } as any
      const mockLogger = createMockLogger()
      const instance = new AuthController(
        mockLogger,
        mockLoginUserUseCase,
        mockRegisterUseCase,
        mockRefreshUseCase,
        mockLogoutUseCase
      )

      expect(instance).toBeDefined()
      expect(instance).toBeInstanceOf(AuthController)
    })
  })

  describe('registerRoutes()', () => {
    it('should register POST /auth/login route', () => {
      const mockApp = {
        post: vi.fn(),
      } as unknown as FastifyInstance

      controller.registerRoutes(mockApp)

      expect(mockApp.post).toHaveBeenCalledTimes(4)

      const postCalls = vi.mocked(mockApp.post).mock.calls

      const loginCall = postCalls.find((call) => call[0] === '/auth/login')
      expect(loginCall).toBeDefined()
      const loginOptions = loginCall?.[1] as any
      expect(loginOptions).toEqual(
        expect.objectContaining({
          config: expect.objectContaining({
            rateLimit: expect.objectContaining({
              max: ENVRate,
              timeWindow: '1 minute',
            }),
          }),
        })
      )
      expect(loginCall?.[2]).toEqual(expect.any(Function))

      const oauthSyncCall = postCalls.find((call) => call[0] === '/auth/oauth-sync')
      expect(oauthSyncCall).toBeDefined()
      const oauthSyncOptions = oauthSyncCall?.[1] as any
      expect(oauthSyncOptions).toEqual(
        expect.objectContaining({
          preHandler: expect.any(Function),
          config: expect.objectContaining({
            rateLimit: expect.objectContaining({
              max: ENVRate,
              timeWindow: '1 minute',
            }),
          }),
        })
      )
      expect(oauthSyncCall?.[2]).toEqual(expect.any(Function))

      const refreshCall = postCalls.find((call) => call[0] === '/auth/refresh')
      expect(refreshCall).toBeDefined()
      const refreshOptions = refreshCall?.[1] as any
      expect(refreshOptions).toEqual(
        expect.objectContaining({
          config: expect.objectContaining({
            rateLimit: expect.objectContaining({
              max: 30,
              timeWindow: '1 minute',
            }),
          }),
        })
      )
      expect(refreshCall?.[2]).toEqual(expect.any(Function))

      const logoutCall = postCalls.find((call) => call[0] === '/auth/logout')
      expect(logoutCall).toBeDefined()
      const logoutOptions = logoutCall?.[1] as any
      expect(logoutOptions).toEqual(
        expect.objectContaining({
          preHandler: expect.any(Function),
        })
      )
      expect(logoutCall?.[2]).toEqual(expect.any(Function))
    })

    it('should bind controller context to route handler', () => {
      const mockApp = {
        post: vi.fn(),
      } as unknown as FastifyInstance

      controller.registerRoutes(mockApp)

      // Verify handler is a bound function
      const loginHandler = vi.mocked(mockApp.post).mock.calls[0]?.[2]

      expect(loginHandler).toBeTypeOf('function')
    })

    it('should register route with correct HTTP method', () => {
      const mockApp = {
        post: vi.fn(),
        get: vi.fn(),
        put: vi.fn(),
        delete: vi.fn(),
      } as unknown as FastifyInstance

      controller.registerRoutes(mockApp)

      expect(mockApp.post).toHaveBeenCalledTimes(4)
      expect(mockApp.get).not.toHaveBeenCalled()
      expect(mockApp.put).not.toHaveBeenCalled()
      expect(mockApp.delete).not.toHaveBeenCalled()
    })
  })

  describe('login()', () => {
    describe('successful login', () => {
      it('should authenticate user with valid credentials', async () => {
        mockRequest.body = {
          email: 'user@example.com',
          password: 'SecurePass123!',
        }

        const mockResult = createMockAuthResult('user@example.com', 'mock.jwt.token', ['user'])
