      providerId: 'google-user-123',
      email: 'oauthuser@example.com',
      name: 'OAuth User',
    }

    const mockOAuthResult = createMockAuthResult('oauthuser@example.com', 'oauth.jwt.token', [
      'user',
    ])

    beforeEach(() => {
