                timeWindow: '1 minute',
              }),
            }),
          }),
          expect.any(Function)
        )
      })

      it('should apply the same rate limit to /auth/oauth-sync as /auth/login', () => {
        const mockApp = {
          post: vi.fn(),
        } as unknown as FastifyInstance

        controller.registerRoutes(mockApp)

        const calls = vi.mocked(mockApp.post).mock.calls
        const loginOptions = calls.find((c) => c[0] === '/auth/login')?.[1] as any
        const oauthSyncOptions = calls.find((c) => c[0] === '/auth/oauth-sync')?.[1] as any

        expect(loginOptions?.config?.rateLimit?.max).toBe(oauthSyncOptions?.config?.rateLimit?.max)
        expect(loginOptions?.config?.rateLimit?.timeWindow).toBe(
          oauthSyncOptions?.config?.rateLimit?.timeWindow
        )
      })

      it('should invoke oauthSync handler when route is called', async () => {
        const mockApp = {
          post: vi.fn(),
        } as unknown as FastifyInstance

        controller.registerRoutes(mockApp)

        const oauthSyncCall = vi
          .mocked(mockApp.post)
          .mock.calls.find((call) => call[0] === '/auth/oauth-sync')
        expect(oauthSyncCall).toBeDefined()

        const oauthSyncHandler = oauthSyncCall![2] as unknown as (
          req: FastifyRequest,
          reply: FastifyReply
        ) => Promise<void>

        vi.mocked(mockRegisterUserWithProviderUseCase.execute).mockResolvedValue(mockOAuthResult)

        await oauthSyncHandler(mockRequest, mockReply)

        expect(mockRegisterUserWithProviderUseCase.execute).toHaveBeenCalled()
        expect(mockReply.code).toHaveBeenCalledWith(200)
      })
    })
  })
