        topP: '0.9',
        frequencyPenalty: '0.0',
        presencePenalty: '0.0',
        topK: 40,
        stopSequences: null,
        seed: null,
        maxRetries: 3,
      }

      vi.mocked(mockAiAdminPort.putChatAIOptions).mockResolvedValue(mockUpdatedOptions)

      await useCase.execute(chatTypeId, dto, mockAuditContext)

      expect(mockLogger.error).not.toHaveBeenCalled()
    })
  })
})

