import { createMockLogger } from '../../../shared/factories/logger.factory.js'

// Mock the database module
vi.mock('../../../../src/infrastructure/database/index.js', () => ({
  db: {
    select: vi.fn(),
    update: vi.fn(),
    insert: vi.fn(),
  },
}))

describe('AIAdminRepository', () => {
  let repository: AIAdminRepository
