        id: uuidv7(),
        chatTypeId,
        prompt: 'Updated prompt',
        maxTokens: 4000,
        temperature: '1.5',
        topP: '0.8',
        frequencyPenalty: '-0.5',
        presencePenalty: '0.5',
        topK: 50,
        stopSequences: ['STOP', 'END'],
        seed: 12345,
        maxRetries: 5,
        createdAt: new Date(),
