        topK: null,
        stopSequences: null,
        seed: null,
        maxRetries: null,
        createdAt: new Date(),
        updatedAt: new Date(),
      })

      await controller.putAIChatSettingsById(mockRequest, mockReply)

      expect(mockPutAIAdminUseCase.execute).toHaveBeenCalledWith(
