        }
      }

      mockRequest.params = { id: chatTypeId }
      mockRequest.body = { prompt: 'Test prompt' }
      vi.mocked(mockPostAIAdminUseCase.execute).mockRejectedValue(
        new CustomException('Conflict detected')
