import { describe, expect, it } from 'vitest'

import { ErrorCode } from '../../../src/shared/constants/error-codes.js'
import { HttpStatus } from '../../../src/shared/constants/http-status.js'
import { BaseException } from '../../../src/shared/exceptions/base.exception.js'
import { ValidationException } from '../../../src/shared/exceptions/validation.exception.js'

describe('ValidationException', () => {
  describe('constructor', () => {
    it('should create a validation exception with message', () => {
      const message = 'Validation failed'
      const exception = new ValidationException(message)

      expect(exception.message).toBe(message)
      expect(exception.code).toBe(ErrorCode.VALIDATION_ERROR)
      expect(exception.statusCode).toBe(HttpStatus.BAD_REQUEST)
    })

    it('should create a validation exception with details', () => {
      const message = 'Invalid input'
      const details = { field: 'email', reason: 'invalid format' }
      const exception = new ValidationException(message, details)

      expect(exception.message).toBe(message)
      expect(exception.details).toEqual(details)
    })

    it('should work without details', () => {
      const exception = new ValidationException('Error without details')
      expect(exception.details).toBeUndefined()
    })

    it('should set the correct name', () => {
      const exception = new ValidationException('Error')
      expect(exception.name).toBe('ValidationException')
    })

    it('should be instance of BaseException and Error', () => {
      const exception = new ValidationException('Error')
      expect(exception).toBeInstanceOf(ValidationException)
      expect(exception).toBeInstanceOf(BaseException)
      expect(exception).toBeInstanceOf(Error)
    })
  })

  describe('properties', () => {
    it('should always have BAD_REQUEST status code', () => {
      const exception1 = new ValidationException('Error 1')
      const exception2 = new ValidationException('Error 2', { field: 'name' })

      expect(exception1.statusCode).toBe(HttpStatus.BAD_REQUEST)
      expect(exception2.statusCode).toBe(HttpStatus.BAD_REQUEST)
      expect(exception1.statusCode).toBe(400)
    })

    it('should always have VALIDATION_ERROR code', () => {
      const exception1 = new ValidationException('Error 1')
      const exception2 = new ValidationException('Error 2', { field: 'name' })

      expect(exception1.code).toBe(ErrorCode.VALIDATION_ERROR)
      expect(exception2.code).toBe(ErrorCode.VALIDATION_ERROR)
    })
  })

  describe('toJSON', () => {
    it('should serialize with all properties', () => {
      const message = 'Validation error'
      const details = { fields: ['email', 'password'] }
      const exception = new ValidationException(message, details)

      const json = exception.toJSON()

      expect(json).toEqual({
        name: 'ValidationException',
        message: message,
        code: ErrorCode.VALIDATION_ERROR,
        statusCode: HttpStatus.BAD_REQUEST,
        details: details,
      })
    })
  })

  describe('common validation scenarios', () => {
    it('should handle single field validation error', () => {
      const exception = new ValidationException('Email is invalid', {
        field: 'email',
        value: 'not-an-email',
        constraint: 'must be valid email format',
      })

      expect(exception.message).toBe('Email is invalid')
      expect(exception.details).toHaveProperty('field', 'email')
    })

    it('should handle multiple field validation errors', () => {
      const exception = new ValidationException('Multiple validation errors', {
        errors: [
          { field: 'email', message: 'invalid format' },
          { field: 'password', message: 'too short' },
          { field: 'age', message: 'must be positive' },
        ],
      })

      expect(exception.message).toBe('Multiple validation errors')
      expect(exception.details?.errors).toHaveLength(3)
    })

    it('should handle validation with custom constraints', () => {
      const exception = new ValidationException('Username validation failed', {
        field: 'username',
        value: 'a',
        constraints: {
          minLength: 3,
          maxLength: 20,
          pattern: '^[a-zA-Z0-9_]+$',
        },
      })

      expect(exception.details).toHaveProperty('constraints')
    })
  })

  describe('error throwing', () => {
    it('should be throwable and catchable', () => {
      expect(() => {
        throw new ValidationException('Validation failed')
      }).toThrow(ValidationException)
    })

    it('should preserve details when caught', () => {
      const details = { field: 'email', reason: 'invalid' }
      const error = new ValidationException('Invalid email', details)
      expect(error).toBeInstanceOf(ValidationException)
      expect(error.details).toEqual(details)
    })
  })
})

test/domain/audit/redact-sensitive-data..source:
import { describe, expect, it } from 'vitest'

import type { CreateAuditLogDTO } from '../../../src/application/ports/audit-log.port.js'
import { AuditAction, EntityType } from '../../../src/domain/audit/entity-type.enum.js'
import {
  redactAuditLogEntry,
  redactCreateAuditLogDTO,
} from '../../../src/domain/audit/redact-sensitive-data.js'

describe('redactAuditLogEntry', () => {
  it('should redact changes field in audit log entry', () => {
    const entry = {
      userId: 'user-123',
      entityType: 'user',
      entityId: 'user-456',
      action: 'update',
      changes: {
        before: { email: 'old@example.com', password: 'oldpass' },
        after: { email: 'new@example.com', password: 'newpass' },
      },
      ipAddress: '192.168.1.1',
      userAgent: 'Mozilla/5.0',
    }

    const result = redactAuditLogEntry(entry)

    expect(result.userId).toBe('user-123')
    expect(result.entityType).toBe('user')
    expect(result.action).toBe('update')
    expect(result.ipAddress).toBe('192.168.1.1')

    const changes = result.changes as any
    expect(changes.before.email).toBe('[REDACTED]')
    expect(changes.before.password).toBe('[REDACTED]')
    expect(changes.after.email).toBe('[REDACTED]')
    expect(changes.after.password).toBe('[REDACTED]')
  })

  it('should handle entry without changes field', () => {
    const entry = {
      userId: 'user-123',
      entityType: 'user',
      entityId: 'user-456',
      action: 'delete',
    }

    const result = redactAuditLogEntry(entry)

    expect(result).toEqual(entry)
  })

  it('should handle entry with null changes', () => {
    const entry = {
      userId: 'user-123',
      entityType: 'user',
      entityId: 'user-456',
      action: 'delete',
      changes: null,
    }

    const result = redactAuditLogEntry(entry)

    expect(result.changes).toBe(null)
  })

  it('should preserve all non-changes fields', () => {
    const entry = {
      userId: 'user-123',
      entityType: 'user',
      entityId: 'user-456',
      action: 'login',
      changes: { success: true, password: 'secret' },
      ipAddress: '10.0.0.1',
      userAgent: 'Chrome',
      customField: 'preserved',
    }

    const result = redactAuditLogEntry(entry)

    expect(result.userId).toBe('user-123')
    expect(result.entityType).toBe('user')
    expect(result.entityId).toBe('user-456')
    expect(result.action).toBe('login')
    expect(result.ipAddress).toBe('10.0.0.1')
    expect(result.userAgent).toBe('Chrome')
    expect(result.customField).toBe('preserved')

    const changes = result.changes as any
    expect(changes.success).toBe(true)
    expect(changes.password).toBe('[REDACTED]')
  })

  it('should handle login failure with email in changes', () => {
    const entry = {
      userId: null,
      entityType: 'user',
      entityId: 'unknown',
      action: 'login_failed',
      changes: {
        email: 'user@example.com',
        password: 'wrongpass',
        reason: 'invalid_password',
      },
    }

    const result = redactAuditLogEntry(entry)

    const changes = result.changes as any
    expect(changes.email).toBe('[REDACTED]')
    expect(changes.password).toBe('[REDACTED]')
    expect(changes.reason).toBe('invalid_password')
  })

  it('should redact tokens in changes', () => {
    const entry = {
      userId: 'user-123',
      entityType: 'user',
      entityId: 'user-456',
      action: 'token_refresh',
      changes: {
        oldToken: 'eyJhbGciOi...',
        newToken: 'eyJhbGciOj...',
        expiresIn: 3600,
      },
    }

    const result = redactAuditLogEntry(entry)

    const changes = result.changes as any
    expect(changes.oldToken).toBe('[REDACTED]')
    expect(changes.newToken).toBe('[REDACTED]')
    expect(changes.expiresIn).toBe(3600)
  })
})

describe('redactCreateAuditLogDTO', () => {
  it('should redact changes field in CreateAuditLogDTO', () => {
    const entry: CreateAuditLogDTO = {
      userId: 'user-123',
      entityType: EntityType.USER,
      entityId: 'user-456',
      action: AuditAction.UPDATE,
      changes: {
        before: { email: 'old@example.com', password: 'oldpass' },
        after: { email: 'new@example.com', password: 'newpass' },
      },
      ipAddress: '192.168.1.1',
      userAgent: 'Mozilla/5.0',
    }

    const result = redactCreateAuditLogDTO(entry)

    expect(result.userId).toBe('user-123')
    expect(result.entityType).toBe(EntityType.USER)
    expect(result.action).toBe(AuditAction.UPDATE)
    expect(result.ipAddress).toBe('192.168.1.1')

    const changes = result.changes as Record<string, unknown>
    const before = changes.before as Record<string, unknown>
    const after = changes.after as Record<string, unknown>
    expect(before.email).toBe('[REDACTED]')
    expect(before.password).toBe('[REDACTED]')
    expect(after.email).toBe('[REDACTED]')
    expect(after.password).toBe('[REDACTED]')
  })

  it('should handle DTO without changes field', () => {
    const entry: CreateAuditLogDTO = {
      userId: 'user-123',
      entityType: EntityType.USER,
      entityId: 'user-456',
      action: AuditAction.DELETE,
    }

    const result = redactCreateAuditLogDTO(entry)

    expect(result).toEqual(entry)
  })

  it('should handle DTO with undefined changes', () => {
    const entry: CreateAuditLogDTO = {
      userId: 'user-123',
      entityType: EntityType.USER,
      entityId: 'user-456',
      action: AuditAction.DELETE,
      changes: undefined,
    }

    const result = redactCreateAuditLogDTO(entry)

    expect(result.changes).toBe(undefined)
  })

  it('should preserve all non-changes fields in DTO', () => {
    const entry: CreateAuditLogDTO = {
      userId: 'user-123',
      entityType: EntityType.USER,
      entityId: 'user-456',
      action: AuditAction.LOGIN,
      changes: { success: true, password: 'secret' },
      ipAddress: '10.0.0.1',
      userAgent: 'Chrome',
    }

    const result = redactCreateAuditLogDTO(entry)

    expect(result.userId).toBe('user-123')
    expect(result.entityType).toBe(EntityType.USER)
    expect(result.entityId).toBe('user-456')
    expect(result.action).toBe(AuditAction.LOGIN)
    expect(result.ipAddress).toBe('10.0.0.1')
    expect(result.userAgent).toBe('Chrome')

    const changes = result.changes as Record<string, unknown>
    expect(changes.success).toBe(true)
    expect(changes.password).toBe('[REDACTED]')
  })

  it('should handle login failure with sensitive data in changes', () => {
    const entry: CreateAuditLogDTO = {
      userId: null,
      entityType: EntityType.USER,
      entityId: 'unknown',
      action: AuditAction.LOGIN_FAILED,
      changes: {
        reason: 'invalid_password',
        token: 'secret-token',
        apiKey: 'secret-key',
      },
    }

    const result = redactCreateAuditLogDTO(entry)

    const changes = result.changes as Record<string, unknown>
    expect(changes.reason).toBe('invalid_password')
    expect(changes.token).toBe('[REDACTED]')
    expect(changes.apiKey).toBe('[REDACTED]')
  })

  it('should maintain type safety with CreateAuditLogDTO', () => {
    const entry: CreateAuditLogDTO = {
      userId: 'user-123',
      entityType: EntityType.USER,
      entityId: 'user-456',
      action: AuditAction.UPDATE,
      changes: {
        before: { name: 'Old', password: 'old' },
        after: { name: 'New', password: 'new' },
      },
    }

    // This should compile without type errors
    const result: CreateAuditLogDTO = redactCreateAuditLogDTO(entry)

    expect(result.userId).toBe('user-123')
    expect(result.entityType).toBe(EntityType.USER)
  })
})

